$(function(){window.addEventListener("scroll",function(){}),document.querySelectorAll(".js-fadeIns01").forEach(function(o){gsap.fromTo(o,{y:20,opacity:0},{y:0,duration:.8,opacity:1,scrollTrigger:{trigger:o,start:"top center"}})}),document.querySelectorAll(".js-parallax01").forEach(function(o){gsap.fromTo(o.querySelector("img"),{yPercent:0},{yPercent:-15,ease:"none",scrollTrigger:{trigger:o,start:"top bottom",end:"bottom top",scrub:.3}}),gsap.fromTo(o,{y:20},{y:0,ease:"none",scrollTrigger:{trigger:o,start:"top bottom",end:"bottom top",scrub:.2}})}),ScrollTrigger.config({autoRefreshEvents:"visibilitychange,DOMContentLoaded,load"})});